function makeEnemy(x,z,type){const g=new THREE.Group();const m=type==='волк'?mats.wolf:mats.fox;sphere(g,m,[0,.62,0],[.43,.43,.75],12);sphere(g,m,[0,.67,.59],[.34,.31,.4],10);sphere(g,type==='лиса'?mats.fox:mat('#77776c'),[0,.55,.91],[.24,.17,.3],9);for(const side of [-1,1]){sphere(g,m,[side*.24,.94,.52],[.11,.25,.1],7);sphere(g,mat('#e7c889'),[side*.17,.74,.85],[.045,.05,.04],6)}const tail=sphere(g,m,[0,.69,-.69],[.2,.22,.55],8);tail.rotation.x=-.5;g.position.set(x,0,z);scene.add(g);enemies.push({group:g,type,hp:type==='волк'?55:35,max:type==='волк'?55:35,attack:0,stun:0,patrol:Math.random()*7,alive:true,speed:type==='волк'?2.15:2.7})}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function refreshUI(){ui.coins.textContent=stats.coins;ui.truffles.textContent=`${stats.truffles} / 5`;ui.kills.textContent=`${stats.kills} / 3`;ui.hpText.textContent=`${Math.ceil(stats.hp)} / ${stats.maxHp}`;ui.hpBar.style.width=`${Math.max(0,stats.hp/stats.maxHp*100)}%`;const objective=stats.truffles<5?'Найди лесные трюфели':stats.kills<3?'Прогони хищников':stats.coins<100?'Собери 100 монет':'Стань сильнее — открой улучшение';ui.objective.textContent=objective;ui.objectiveSub.textContent=stats.truffles<5?`Собери ещё ${5-stats.truffles} трюфелей. Следуй за золотыми искрами.`:stats.kills<3?`Осталось прогнать ${3-stats.kills} хищников. Используй таран.`:stats.coins<100?`Найди монеты на тропе: ${stats.coins} из 100.`:'Купи любое улучшение в лавке лесника.';document.querySelectorAll('.upgrade').forEach(b=>b.disabled=stats.coins<Number(b.dataset.up==='health'?30:b.dataset.up==='speed'?25:35));$('#upgradeInfo').textContent=`Монеты: ${stats.coins} · Здоровье ${stats.healthLv} · Скорость ${stats.speedLv} · Таран ${stats.damageLv}`}
function addCoins(n){stats.coins+=n;refreshUI();if(stats.coins>=100)achievement('Сребролюбец','Собрано 100 монет!')}
function achievement(name,description){showToast(`🏅 ${name}: ${description}`)}
function search(){if(!gameStarted||paused||over)return;if(player.searchCd>0){showToast('Немного подожди — кабан устал нюхать.');return}player.searchCd=2.2;boar.userData.dig=.95;let nearest=null,dist=2.8;for(const p of patches){const d=player.pos.distanceTo(p.group.position);if(d<dist&&p.ready){nearest=p;dist=d}}if(nearest){nearest.ready=false;nearest.item.visible=true;nearest.respawn=18;nearest.item.position.y=.36;stats.truffles++;addCoins(nearest.value);showToast(`${nearest.kind} найден! +${nearest.value} монет`);if(stats.truffles===10)achievement('Чуткий нос','Найдено 10 трюфелей!');refreshUI()}else{showToast('Кабан нюхает землю… здесь пока пусто. Ищи грядку с листьями.');}}
function attack(){if(!gameStarted||paused||over||player.attackCd>0)return;player.attackCd=.8;boar.userData.charge=.32;const dir=new THREE.Vector3(Math.sin(player.face),0,Math.cos(player.face));let hit=false;for(const e of enemies){if(!e.alive)continue;const delta=e.group.position.clone().sub(player.pos);const forward=delta.clone().normalize().dot(dir);if(delta.length()<3.35&&forward>.1){e.hp-=stats.damage;e.stun=.65;e.group.position.addScaledVector(dir,1.05);showToast(`Таран! ${e.type==='волк'?'Волк':'Лиса'} отступает.`);hit=true;if(e.hp<=0){e.alive=false;e.group.visible=false;stats.kills++;addCoins(18);showToast(`Хищник прогнан! +18 монет`);if(stats.kills===5)achievement('Хозяин чащи','Прогнано 5 хищников!');refreshUI()}break}}if(!hit)showToast('Таран в пустоту! Подойди поближе к хищнику.')}
function hurt(n){if(player.invuln>0)return;stats.hp=Math.max(0,stats.hp-n);player.invuln=1.1;showToast('Хищник кусает! Отойди или тарани его.');refreshUI();if(stats.hp<=0){over=true;paused=true;$('#endTitle').textContent='Лесная передышка';$('#endText').textContent=`Поход закончен. Ты нашёл ${stats.truffles} трюфелей, прогнал ${stats.kills} хищников и собрал ${stats.coins} монет. Лес будет ждать тебя снова.`;$('#endScreen').classList.remove('hidden')}}
