function begin(){gameStarted=true;paused=false;$('#startScreen').classList.add('hidden');if(audioOn)startAmbience();renderer.domElement.requestPointerLock?.();showToast('Удачной охоты, лесной бродяга!')}
function togglePause(){if(!gameStarted||over)return;paused=!paused;$('#pauseScreen').classList.toggle('hidden',!paused);if(paused)document.exitPointerLock?.()}
function openUpgrade(){const wasPaused=paused;paused=true;$('#pauseScreen').classList.add('hidden');$('#upgradeScreen').classList.remove('hidden');refreshUI();$('#upgradeScreen').dataset.wasPaused=String(wasPaused)}
function closeUpgrade(){const wasPaused=$('#upgradeScreen').dataset.wasPaused==='true';$('#upgradeScreen').classList.add('hidden');paused=wasPaused;if(wasPaused)$('#pauseScreen').classList.remove('hidden')}
function buy(type){const price=type==='health'?30:type==='speed'?25:35;if(stats.coins<price){showToast('Не хватает монет.');return}stats.coins-=price;if(type==='health'){stats.healthLv++;stats.maxHp+=25;stats.hp=Math.min(stats.maxHp,stats.hp+25)}else if(type==='speed'){stats.speedLv++;stats.speed+=.55}else{stats.damageLv++;stats.damage+=12}showToast('Улучшение куплено!');refreshUI();if(stats.healthLv+stats.speedLv+stats.damageLv===1)achievement('Лесной умелец','Куплено первое улучшение!')}
